function addProductQty(prodId,qty){const q=ensure(),p=A.state.catalog.find(x=>x.id===prodId);if(!p)return false;const cost=A.nativeNetUSD(p);if(cost===null)return false;const existing=q.items.find(x=>x.productId===prodId&&num(x.sourceCost||x.cost)===num(p.cost));if(existing)existing.quantity+=qty;else q.items.push({id:A.makeId(),productId:prodId,name:p.name,description:p.description,category:p.category,quantity:qty,cost,sourceCost:p.cost,sourceCurrency:p.currency||'USD',sourceTaxIncluded:!!p.taxIncluded,autoSale:true,sale:Number((Number.isFinite(p.salePrice)?(p.currency==='UYU'?p.salePrice/num(q.fxRate):p.salePrice):A.suggestSale(cost)).toFixed(5)),autoSale:!Number.isFinite(p.salePrice)});return true}
