async function addChannelTask(){const p=materialPlan();if(p.channel<=0){A.toast('Todavía no relevaste metros de canalización.',true);return}const q=ensure();const found=q.installTasks.find(x=>x.id==='safe-auto-canalizacion');if(found){if(!await A.safeConfirm('Ya existe una tarea de canalización generada desde el relevamiento. ¿Actualizar su metraje?'))return;found.qty=p.channel}else q.installTasks.push({id:'safe-auto-canalizacion',name:'Canalización adicional relevada',qty:p.channel,price:2.5,cost:0,unit:'m'});A.refreshAll();apply();A.toast('Canalización añadida como tarea editable de Instalación técnica.');}
