const MAX_PACKAGES=60;
function defaultIds(){return new Set(defaults.map(x=>x.id))}
function deletedDefaultIds(){return new Set((A.state.packages||[]).filter(x=>x.deleted&&defaultIds().has(x.id)).map(x=>x.id))}
function packages(){const list=A.state.packages||[],removed=deletedDefaultIds(),overrides=new Map(list.filter(x=>!x.deleted).map(x=>[x.id,x]));return [...defaults.filter(x=>!removed.has(x.id)).map(x=>overrides.get(x.id)||x),...list.filter(x=>!x.deleted&&!defaults.some(d=>d.id===x.id))]}
